architecture rtl of conv_demo is
  signal a_slv : std_logic_vector(7 downto 0);
  signal u     : unsigned(7 downto 0);
  signal s     : signed(7 downto 0);
  signal n     : integer range 0 to 255;
begin
  a_slv <= std_logic_vector(to_unsigned(200, 8));  -- integer to bits
  u     <= unsigned(a_slv);                        -- cast, same bits
  n     <= to_integer(u);                          -- 200
  s     <= resize(signed(a_slv(3 downto 0)), 8);   -- sign-extend
end architecture rtl;

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity add4 is
  port (a, b : in  unsigned(3 downto 0);
        sum  : out unsigned(3 downto 0);
        cout : out std_logic);
end entity add4;
architecture rtl of add4 is
  signal t : unsigned(4 downto 0);
begin
  t    <= resize(a, 5) + resize(b, 5);   -- 5-bit sum keeps the carry
  sum  <= t(3 downto 0);
  cout <= t(4);
end architecture rtl;

entity sadd8 is
  port (a, b : in  signed(7 downto 0);
        sum  : out signed(7 downto 0);
        ovf  : out std_logic);
end entity sadd8;
architecture rtl of sadd8 is
  signal s : signed(7 downto 0);
begin
  s   <= a + b;                                   -- wraps on overflow
  sum <= s;
  ovf <= (a(7) xnor b(7)) and (s(7) xor a(7));    -- same signs in, sign flipped
end architecture rtl;

