-- 4-bit ripple-carry adder built from full adders
c(0) <= cin;
gen_rca : for i in 0 to 3 generate
  s(i)   <= a(i) xor b(i) xor c(i);
  c(i+1) <= (a(i) and b(i)) or (c(i) and (a(i) xor b(i)));
end generate gen_rca;
cout <= c(4);

-- D flip-flop with asynchronous active-high reset
process (clk, rst)
begin
  if rst = '1' then
    q <= '0';
  elsif rising_edge(clk) then
    q <= d;
  end if;
end process;

-- 4-bit up counter, cnt declared as unsigned(3 downto 0)
process (clk)
begin
  if rising_edge(clk) then
    if rst = '1' then
      cnt <= (others => '0');    -- synchronous reset
    elsif en = '1' then
      cnt <= cnt + 1;            -- wraps 15 -> 0
    end if;
  end if;
end process;
q <= std_logic_vector(cnt);

-- declarative part: type state_t is (IDLE, RUN); signal state : state_t;
process (clk, rst)
begin
  if rst = '1' then
    state <= IDLE;
  elsif rising_edge(clk) then
    case state is
      when IDLE => if start = '1' then state <= RUN;  end if;
      when RUN  => if stop  = '1' then state <= IDLE; end if;
    end case;
  end if;
end process;
busy <= '1' when state = RUN else '0';   -- Moore output

-- Worked example 1: overlapping 101 detector, Moore version
type st_t is (S0, S1, S10, S101);   -- S101 means "101 seen"
process (clk) begin
  if rising_edge(clk) then
    case st is
      when S0   => if x = '1' then st <= S1;   end if;
      when S1   => if x = '0' then st <= S10;  end if;
      when S10  => if x = '1' then st <= S101; else st <= S0;  end if;
      when S101 => if x = '1' then st <= S1;   else st <= S10; end if;
    end case;
  end if;
end process;
z_moore <= '1' when st = S101 else '0';
-- Mealy version: states M0, M1, M10 and z_mealy <= '1' when st = M10 and x = '1'

-- cnt : unsigned(15 downto 0); N = 50_000 gives a 1 kHz tick from 50 MHz
process (clk)
begin
  if rising_edge(clk) then
    tick <= '0';                    -- default: low
    if cnt = N - 1 then
      cnt  <= (others => '0');
      tick <= '1';                  -- high for one clock every N clocks
    else
      cnt <= cnt + 1;
    end if;
  end if;
end process;

