library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity mac_pipe is
  port (clk, vin : in  std_logic;
        a, b, c  : in  unsigned(7 downto 0);
        y        : out unsigned(15 downto 0);
        vout     : out std_logic);
end entity mac_pipe;
architecture rtl of mac_pipe is
  signal prod : unsigned(15 downto 0);
  signal c_d  : unsigned(7 downto 0);
  signal v1   : std_logic;
begin

  process (clk)                          -- y = a*b + c in 2 stages
  begin
    if rising_edge(clk) then
      prod <= a * b;                     -- stage 1: multiply
      c_d  <= c;                         -- delay c to stay aligned
      v1   <= vin;
      y    <= prod + resize(c_d, 16);    -- stage 2: add
      vout <= v1;                        -- valid follows the data
    end if;
  end process;
end architecture rtl;

-- Worked example 2: y = a + b + c + d in two stages (ieee.numeric_std)
-- ports: clk; a, b, c, d : in unsigned(7 downto 0);
--        y : out unsigned(9 downto 0)
architecture rtl of sum4_pipe is
  signal s1, s2 : unsigned(8 downto 0) := (others => '0');
begin
  process (clk)
  begin
    if rising_edge(clk) then
      s1 <= resize(a, 9) + resize(b, 9);       -- stage 1
      s2 <= resize(c, 9) + resize(d, 9);       -- stage 1
      y  <= resize(s1, 10) + resize(s2, 10);   -- stage 2
    end if;
  end process;
end architecture;

